sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.confirmation-container {
  max-width: 700px;
  margin: 40px auto;
  font-family: Arial, sans-serif;
  text-align: center;
}

.status-message {
  background-color: #e6f4ea;
  color: #2e7d32;
  border-radius: 8px;
  padding: 20px;
  margin-bottom: 30px;
  display: inline-block;
  text-align: left;
}

.status-icon {
  font-size: 24px;
  font-weight: bold;
  display: inline-block;
  margin-right: 10px;
  color: #2e7d32;
}

.steps-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 30px;
  position: relative;
}

.step {
  text-align: center;
  flex: 1;
  position: relative;
}

.step:not(:last-child)::after {
  content: '';
  position: absolute;
  top: 15px;
  right: -50%;
  width: 100%;
  height: 4px;
  background-color: #4caf50;
  z-index: -1;
}

.step.pending:not(:last-child)::after {
  background-color: #cfd8dc;
}

.circle {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background-color: #4caf50;
  color: white;
  line-height: 30px;
  margin: 0 auto 10px auto;
}

.step.pending .circle {
  background-color: white;
  border: 2px solid #cfd8dc;
  color: transparent;
}

.label {
  font-weight: bold;
  margin-bottom: 5px;
}

.date {
  font-size: 12px;
  color: #555;
}

.actions {
  margin-top: 20px;
}

.btn-primary {
  padding: 10px 20px;
  background-color: #1976d2;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
}

.btn-primary:hover {
  background-color: #1565c0;
}
